// Safeguard marker: INSTAOPS_V2_PUBLISH — Meta Graph API v22.0 for Reels, Images, and 2-10 Mixed Carousels.
const item = $input.first().json || {};
const headers = item.headers || {};
const body = item.body || item;
const expected = String($env.N8N_WEBHOOK_SECRET || '');
const provided = String(headers['x-dashboard-secret'] || headers['X-Dashboard-Secret'] || '');

function safeEqual(a, b) {
  if (!a || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

const postUuid = String(body.post_uuid || '').trim();
const postId = String(body.post_id || '').trim();
const igUserId = String(body.ig_user_id || $env.INSTAGRAM_USER_ID || '17841453414532595').trim();
const reviewedRevision = String(body.reviewed_revision || '').trim();
const mediaType = String(body.media_type || 'REEL').toUpperCase();
const mediaItems = Array.isArray(body.media_items) ? body.media_items : [];

let error = '';
if (!expected || !safeEqual(provided, expected)) {
  error = 'Unauthorized webhook secret.';
} else if (body.confirm !== true || !postId || !reviewedRevision) {
  error = 'Explicit confirmation and reviewed_revision are required.';
} else if (mediaType === 'CAROUSEL' && (mediaItems.length < 2 || mediaItems.length > 10)) {
  error = `Carousel publishing requires 2-10 active assets (received ${mediaItems.length}).`;
}

return [{
  json: {
    valid: !error,
    error,
    httpStatus: error.includes('Unauthorized') ? 403 : error ? 422 : 202,
    post_uuid: postUuid,
    post_id: postId,
    ig_user_id: igUserId,
    reviewed_revision: reviewedRevision,
    media_type: mediaType,
    media_url: String(body.media_url || ''),
    media_items: mediaItems,
    caption: String(body.caption || ''),
    request_id: String(body.request_id || ''),
    job_id: String(body.job_id || ''),
    execution_id: String($execution.id || '')
  }
}];

const req = $('CODE | Verify Auth & Approval Gate').item.json;
const rows = $input.all().map(i => i.json);
const row = Array.isArray(rows[0]) ? rows[0][0] : rows[0];
if (!row || !row.id) {
  return [{ json: { canProceed: false, reason: 'Post missing in Supabase.' } }];
}
const revision = String(row.revision || '');
const approved_revision = String(row.approved_revision ?? '');
const status = String(row.status || '').toUpperCase();
const mediaType = String(row.media_type || req.media_type).toUpperCase();
if (status === 'PUBLISHED' || Boolean(row.published_id)) {
  return [{ json: { canProceed: false, reason: 'Duplicate protection: already published.' } }];
}
if (revision !== req.reviewed_revision && approved_revision !== revision) {
  return [{ json: { canProceed: false, reason: `Revision mismatch (reviewed=${req.reviewed_revision}, revision=${revision}).` } }];
}
const activeAssets = (Array.isArray(row.instaops_media_assets) ? row.instaops_media_assets : req.media_items)
  .filter(a => !a.storage_status || a.storage_status === 'ACTIVE')
  .sort((a, b) => Number(a.media_index || 0) - Number(b.media_index || 0));

if (mediaType === 'CAROUSEL' && (activeAssets.length < 2 || activeAssets.length > 10)) {
  return [{ json: { canProceed: false, reason: 'Carousel requires 2-10 ACTIVE assets.' } }];
}

return [{
  json: {
    canProceed: true,
    post_uuid: row.id,
    post_id: row.post_id,
    ig_user_id: req.ig_user_id,
    media_type: mediaType,
    isCarousel: mediaType === 'CAROUSEL',
    caption: String(row.caption || row.original_caption || req.caption || ''),
    media_url: String(row.media_url || (activeAssets[0] && activeAssets[0].secure_url) || req.media_url),
    approved_revision: Number(req.reviewed_revision) || 1,
    assets: activeAssets,
    execution_id: req.execution_id,
    request_id: req.request_id
  }
}];

const ctx = $('CODE | Re-verify Approved Revision & Build Container Requests').item.json;
return ctx.assets.map((a, idx) => ({
  json: {
    post_uuid: ctx.post_uuid,
    ig_user_id: ctx.ig_user_id,
    media_index: idx,
    asset_id: a.id || null,
    isVideo: String(a.resource_type || a.media_type).toLowerCase() === 'video',
    secure_url: String(a.secure_url)
  }
}));

const ctx = $('CODE | Re-verify Approved Revision & Build Container Requests').item.json;
const childIds = $input.all().map(i => String((i.json && i.json.id) || '')).filter(Boolean);
return [{
  json: {
    post_uuid: ctx.post_uuid,
    ig_user_id: ctx.ig_user_id,
    caption: ctx.caption,
    childIds,
    childrenCsv: childIds.join(',')
  }
}];

const res = $input.first().json || {};
const ctx = $('CODE | Re-verify Approved Revision & Build Container Requests').item.json;
return [{ json: { container_id: String(res.id || ''), post_uuid: ctx.post_uuid, ig_user_id: ctx.ig_user_id } }];

const res = $input.first().json || {};
const code = String(res.status_code || res.status || '').toUpperCase();
const ready = code === 'FINISHED' || code === 'PUBLISHED';
const meta = $('CODE | Unify Container ID').item.json;
return [{ json: { status_code: code, ready, container_id: meta.container_id, ig_user_id: meta.ig_user_id } }];
